css:
.button {
  padding: 7px 10px;
  border: 1px solid #bbb;
  color: #222;
  font-weight: 600;
  cursor: pointer;
  border-radius: 4px;
  box-shadow: 0 10px 20px rgba(0,0,0,0.2);
  transition: all .3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.button:hover {
  background-color: #007ffe;
  color: #fff;
  box-shadow: -20px 50px 50px rgba(0,0,0,0.2);
  border: none;
  padding: 10px 20px;
}
